import json

def parse_json(json_str):
    # Check for syntax errors
    if not json_str or json_str[0] not in ['{', '[']:
        raise ValueError("Invalid JSON syntax")

    # Initialize the result structure
    result = None

    # Parse the JSON string
    if json_str[0] == '{':
        result = parse_object(json_str)
    elif json_str[0] == '[':
        result = parse_array(json_str)
    else:
        result = parse_value(json_str)

    return result

def parse_object(json_str):
    # Skip the opening brace
    json_str = json_str[1:]

    # Initialize the object
    obj = {}

    # Parse key-value pairs
    while json_str:
        key = parse_key(json_str)
        json_str = json_str[key:]
        value = parse_value(json_str)
        obj[key] = value

        # Check for comma or closing brace
        if json_str and json_str[0] in ',]':
            json_str = json_str[1:]
        else:
            break

    # Skip the closing brace
    json_str = json_str[1:]

    return obj

def parse_array(json_str):
    # Skip the opening bracket
    json_str = json_str[1:]

    # Initialize the array
    arr = []

    # Parse elements
    while json_str:
        elem = parse_value(json_str)
        arr.append(elem)

        # Check for comma or closing brace
        if json_str and json_str[0] in ',]':
            json_str = json_str[1:]
        else:
            break

    # Skip the closing brace
    json_str = json_str[1:]

    return arr

def parse_value(json_str):
    # Check for string
    if json_str[0] in '"':
        return parse_string(json_str)

    # Check for number
    if json_str[0] in '-0123456789.eE':
        return parse_number(json_str)

    # Check for boolean
    if json_str.lower() in ['true', 'false']:
        return parse_boolean(json_str)

    # Check for null
    if json_str.lower() == 'null':
        return None

    # Raise an exception for unknown values
    raise ValueError("Unknown JSON value")

def parse_string(json_str):
    # Skip the opening and closing quotes
    json_str = json_str[1:-1]

    # Parse escaped characters
    escaped = False
    result = ''
    for char in json_str:
        if escaped:
            result += char
            escaped = False
        elif char == '\\':
            escaped = True
        else:
            result += char

    return result

def parse_number(json_str):
    # Parse the number
    result = ''
    for char in json_str:
        if char in '-0123456789.eE':
            result += char
        else:
            break

    # Parse the exponent
    if json_str and json_str[0] in 'eE':
        json_str = json_str[1:]
        if json_str[0] in '+-':
            json_str = json_str[1:]
        exponent = ''
        for char in json_str:
            if char in '0123456789':
                exponent += char
            else:
                break
        result += 'e' + exponent

    return float(result)

def parse_boolean(json_str):
    # Parse the boolean
    if json_str.lower() == 'true':
        return True
    elif json_str.lower() == 'false':
        return False
    else:
        raise ValueError("Unknown JSON boolean")

