    obj = {}

    # Iterate over the key-value pairs
    for pair in pairs:
        # Split the pair into key and value
        key, value = pair.split(':')

        # Remove leading and trailing whitespace
        key = key.strip()
        value = value.strip()

        # Check if the key is valid
        if not key:
