import re

def parse_json(json_str):
    # Check for syntax errors
    if not re.match(r'^[\{\[].*[\}\]]$', json_str):
        raise SyntaxError("Invalid JSON syntax")

    # Initialize the result structure
    result = None

    # Parse the JSON string
    if json_str[0] == '{':
        result = {}
        key = None
        while json_str:
            if json_str[0] == '"':
                key = ''
                json_str = json_str[1:]
                while json_str and json_str[0] != '"':
                    key += json_str[0]
                    json_str = json_str[1:]
                json_str = json_str[1:]
                if json_str and json_str[0] == ':':
                    json_str = json_str[1:]
                    value = parse_json(json_str)
                    result[key] = value
                else:
                    raise ValueError("Invalid JSON structure")
            elif json_str[0] == '[':
                result = []
                json_str = json_str[1:]
                while json_str and json_str[0] != ']':
                    value = parse_json(json_str)
                    result.append(value)
                    json_str = json_str[1:]
                json_str = json_str[1:]
            elif json_str[0] in '0123456789.-':
                value = ''
                while json_str and json_str[0] in '0123456789.-':
                    value += json_str[0]
                    json_str = json_str[1:]
                if json_str and json_str[0] in 'eE':
                    json_str = json_str[1:]
                    value += json_str[0]
                    json_str = json_str[1:]
                    while json_str and json_str[0] in '0123456789':
                        value += json_str[0]
                        json_str = json_str[1:]
                result = float(value)
            elif json_str[0] in 'tT':
                result = True
                json_str = json_str[1:]
            elif json_str[0] in 'fF':
                result = False
                json_str = json_str[1:]
            elif json_str[0] in 'nN':
                result = None
                json_str = json_str[1:]
            elif json_str[0] == '"':
                value = ''
                json_str = json_str[1:]
                while json_str and json_str[0] != '"':
                    value += json_str[0]
                    json_str = json_str[1:]
                json_str = json_str[1:]
                result = value
            else:
                raise ValueError("Invalid JSON structure")

    return result

