    if not json_str.startswith('{') and not json_str.startswith('['):
        raise SyntaxError("Invalid JSON syntax")

    # Initialize the result structure
    result = None

    # Parse the JSON string
    if json_str.startswith('{'):
        result = {}
        while json_str:
            if json_str[0] == '}':
                break
            key = json_str.split(':')[0].strip()
            json_str = json_str.split(':')[1].strip()
            if json_str[0] == '"':
                value = json_str[1:-1].strip()
            else:
                value = json_str.strip()
            result[key] = parse_json(value)
            json_str = json_str.lstrip()
    elif json_str.startswith('['):
        result = []
        while json_str:
            if json_str[0] == ']':
                break
            value = parse_json(json_str)
            result.append(value)
            json_str = json_str.lstrip()
    else:
        # Handle basic types
        if json_str.isdigit():
            result = int(json_str)
        elif json_str.replace('.', '', 1).isdigit():
            result = float(json_str)
        elif json_str.lower() in ['true', 'false']:
            result = json_str.lower() == 'true'
        elif json_str == 'null':
            result = None
        else:
            result = json_str

