    if not json_str:
        raise ValueError("JSON string cannot be empty")

    # Remove leading and trailing whitespace
    json_str = json_str.strip()

    # Check if the JSON string starts with a valid JSON object or array
    if json_str[0] in ('{', '['):
        return parse_object_or_array(json_str)
    else:
        raise ValueError("Invalid JSON string")

def parse_object_or_array(json_str):
    # Check if the JSON string is an object
    if json_str[0] == '{':
        return parse_object(json_str)
    # Check if the JSON string is an array
    elif json_str[0] == '[':
        return parse_array(json_str)
    else:
        raise ValueError("Invalid JSON string")

def parse_object(json_str):
    # Remove the opening brace
    json_str = json_str[1:]

    # Initialize the result dictionary
    result = {}

    # Loop through the JSON string until the closing brace is found
    while json_str:
        # Find the first colon
        colon_index = json_str.find(':')
        if colon_index == -1:
            raise ValueError("Invalid JSON string")

        # Extract the key
        key = json_str[:colon_index].strip()

        # Remove the colon
        json_str = json_str[colon_index + 1:]

        # Find the first comma or closing brace
        comma_or_brace_index = json_str.find(',', json_str.find('{') + 1)
        if comma_or_brace_index == -1:
            comma_or_brace_index = json_str.find('}', json_str.find('{') + 1)

        # Extract the value
        value = json_str[:comma_or_brace_index].strip()

        # Remove the comma or closing brace
        json_str = json_str[comma_or_brace_index + 1:]

        # Add the key-value pair to the result dictionary
        result[key] = parse_value(value)

    # Remove the closing brace
    json_str = json_str[1:]

    return result

def parse_array(json_str):
